// Flat list of all available icon names (sorted alphabetically).
export const MDI_NAMES = Object.keys(MDI_PATHS).sort()

// Get the SVG path for an icon, or null when the name isn't in the catalog.
// Consumers: pd-icon renders this inside an <svg viewBox="0 0 24 24">.
export function getIconPath(name) {
  return MDI_PATHS[name] || null
}
